import { expect, test } from './fixtures';
import type { Page } from '@playwright/test';

/**
 * SELECT in a catalog, its frame (Select-Tablet), in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/handoffs/browse-select/Select-Tablet.dc.html
 * Extracted at 2026-11-10T22:26:32.671Z at 1440x2400.
 *
 * It runs in the browse project (its name) against tests/browse-setup.ts's
 * fake engine, on Open Source's POPULAR: its first result is IN LIBRARY (the
 * not-tickable tile), and the second is ticked. SELECT lives in the tab's
 * memory, never the URL, so no address arrives selecting: each
 * case opens the page and presses SELECT (`openSelecting`, below). The tab
 * row's POPULAR, LATEST and FILTER are the page's own tabs, unchanged by this
 * card, and are not in the map; the mock redraws them in its own shorthand.
 * Measurements the generator does not propose (the bulk bar's line and cells,
 * the box, the ring, SHOW's rows) are pinned in the sibling
 * tests/browse-select-measure.e2e.ts.
 *
 * Generated from a map whose `app` selectors are SEL below (url /browse/100;
 * regions 3 to 5, the tabs, left blank), then four things changed by
 * hand: this line, the import (the suite's fixtures), the viewport, and each case's
 * `page.goto` replaced by `openSelecting`. Regenerating overwrites this file;
 * make those changes again. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

// The board is the tablet's, 1280x800 (Select-Tablet); the browse project's
// own is the tablet at 800x1280, so this file sets the drawn one.
test.use({ viewport: { width: 1280, height: 800 } });

/** Open Source's POPULAR, selecting, its first tickable result ticked. */
async function openSelecting(page: Page) {
	await page.goto(`${base}/browse/100`);
	await page.getByRole('button', { name: 'SELECT', exact: true }).click();
	await page.locator('.grid button.tile').first().click();
	await expect(page.locator('.grid button.tile[aria-pressed="true"]')).toHaveCount(1);
}

const SEL = {
	frame: 'body',
	region1: 'header[aria-label="Selection"] .count',
	region2: 'nav[aria-label="Lists"] .tab.where',
	region6: '.grid',
	region7: '.grid button.tile[aria-pressed="true"] >> nth=0',
	region8: '.grid .tile.off >> nth=0',
	region12: '.grid button.tile[aria-pressed="false"] >> nth=0',
	region14: '.bulk .acts'
};

test('selecting: frame matches the handoff', async ({ page }) => {
	await openSelecting(page);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('selecting: region1 matches the handoff', async ({ page }) => {
	await openSelecting(page);
	await expect(page.locator(SEL.region1)).toBeVisible();

	const region1Style = await page.locator(SEL.region1).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingRight: cs.paddingRight,
			paddingLeft: cs.paddingLeft,
			borderLeftWidth: cs.borderLeftWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight
		};
	});
	expect(region1Style.display).toBe('flex');
	expect(region1Style.alignItems).toBe('center');
	expect(region1Style.rowGap).toBe('10px');
	expect(region1Style.columnGap).toBe('10px');
	expect(region1Style.paddingRight).toBe('18px');
	expect(region1Style.paddingLeft).toBe('18px');
	expect(region1Style.borderLeftWidth).toBe('1px');
	expect(region1Style.fontSize).toBe('17px');
	expect(region1Style.fontWeight).toBe('500');
});

